-- 0005: what event processing needs. See ADR 0013.
--
-- Two changes: events remember which accepted batch they arrived in, so a job can point at a
-- batch; and event_aggregates holds the first thing derived from events, a count per project per
-- hour. Aggregates are always recomputed from events, never adjusted by a delta, so running the
-- same job again gives the same rows.

-- The id of the accepted batch an event came in. Generated by ingestion, one per request that
-- stored at least one new event, and the subject of the job that processes that batch. Nullable
-- only because a column added to an existing table cannot be required for rows that already
-- exist; ingestion always sets it. Events stay immutable: it is written at insert and never
-- changed. A batch is not a row of its own, so there is nothing else to isolate or retain.
ALTER TABLE events ADD COLUMN batch_id uuid;

-- A job looks up its batch's events by this. Partial, so events from before this migration cost
-- nothing.
CREATE INDEX events_batch_idx ON events (organisation_id, batch_id) WHERE batch_id IS NOT NULL;

-- Events counted per project per hour (UTC), by the time the event says it happened, not the
-- time it arrived, so a late event lands in the hour it belongs to.
CREATE TABLE event_aggregates (
  organisation_id uuid NOT NULL REFERENCES organisations (id) ON DELETE RESTRICT,
  project_id      uuid NOT NULL,
  -- The start of the hour. The check keeps every row on a whole hour, so two writers can never
  -- count the same hour under two different keys.
  bucket_start    timestamptz NOT NULL
                  CHECK (bucket_start = date_bin('1 hour', bucket_start, timestamptz '2000-01-01 00:00:00+00')),
  event_count     bigint NOT NULL CHECK (event_count >= 0),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (organisation_id, project_id, bucket_start),
  FOREIGN KEY (organisation_id, project_id) REFERENCES projects (organisation_id, id) ON DELETE RESTRICT
);

ALTER TABLE event_aggregates ENABLE ROW LEVEL SECURITY;
ALTER TABLE event_aggregates FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON event_aggregates
  TO codemugs_app
  USING (organisation_id = nullif(current_setting('app.organisation_id', true), '')::uuid)
  WITH CHECK (organisation_id = nullif(current_setting('app.organisation_id', true), '')::uuid);

-- Read, create, and change the count. Which hour, which project and whose it is can never change.
-- No DELETE: derived rows are rebuilt by running the job again, and removing them for retention
-- needs a deliberate path that does not exist yet (release gate 15).
GRANT SELECT, INSERT ON event_aggregates TO codemugs_app;
GRANT UPDATE (event_count, updated_at) ON event_aggregates TO codemugs_app;
